module max_queens_4x4 (\n    input clk,\n    input rst_n,\n    input start,\n    input [15:0] broken,  // 1=broken cell, 0=usable\n    output reg [3:0] max_queens,\n    output reg [15:0] num_ways,\n    output reg done\n);\n    // Parameters\n    parameter BOARD_SIZE = 16;\n    parameter MAX_TRIANGLES = 560; // Number of triangles in 4x4 board\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] CHECK_BROKEN = 3'd2;\n    localparam [2:0] POPCOUNT = 3'd3;\n    localparam [2:0] CHECK_TRIANGLE = 3'd4;\n    localparam [2:0] UPDATE_MAX = 3'd5;\n    localparam [2:0] NEXT_SUBSET = 3'd6;\n    localparam [2:0] DONE = 3'd7;\n\n    // Registers\n    reg [2:0] state;\n    reg [15:0] subset;\n    reg [3:0] max_q;\n    reg [15:0] ways;\n    reg [3:0] popcnt;\n    reg [9:0] tri_idx; // 0 to 559\n    reg triangle_found;\n    reg [15:0] current_mask;\n    reg [3:0] bit_idx; // for popcount loop\n    reg [15:0] temp_mask; // for triangle check\n\n    // Triangle table: precomputed for 4x4 board\n    // Each entry is a 16-bit mask of three cells that form a triangle\n    reg [15:0] triangle_mask [0:MAX_TRIANGLES-1];\n\n    // Initialize triangle table (generated by Python script)\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            for (i = 0; i < MAX_TRIANGLES; i = i + 1) begin\n                triangle_mask[i] <= 16'd0;\n            end\n        end\n    end\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            subset <= 16'b0;\n            max_q <= 4'b0;\n            ways <= 16'b0;\n            popcnt <= 4'b0;\n            tri_idx <= 10'b0;\n            triangle_found <= 1'b0;\n            done <= 1'b0;\n            bit_idx <= 4'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= INIT;\n                        done <= 1'b0;\n                    end\n                end\n\n                INIT: begin\n                    subset <= 16'b0;\n                    max_q <= 4'b0;\n                    ways <= 16'b0;\n                    state <= CHECK_BROKEN;\n                end\n\n                CHECK_BROKEN: begin\n                    // Check if current subset intersects broken cells\n                    if (|(subset & broken)) begin\n                        // Skip this subset\n                        state <= NEXT_SUBSET;\n                    end else begin\n                        // Initialize popcount variables\n                        popcnt <= 4'b0;\n                        bit_idx <= 4'b0;\n                        state <= POPCOUNT;\n                    end\n                end\n\n                POPCOUNT: begin\n                    if (bit_idx < 4'd16) begin\n                        if (subset[bit_idx]) begin\n                            popcnt <= popcnt + 1'b1;\n                        end\n                        bit_idx <= bit_idx + 1'b1;\n                    end else begin\n                        // Popcount done, initialize triangle check\n                        tri_idx <= 10'b0;\n                        triangle_found <= 1'b0;\n                        state <= CHECK_TRIANGLE;\n                    end\n                end\n\n                CHECK_TRIANGLE: begin\n                    if (tri_idx < MAX_TRIANGLES) begin\n                        current_mask <= triangle_mask[tri_idx];\n                        // Check if triangle_mask[tri_idx] is subset of subset\n                        if ((subset & current_mask) == current_mask) begin\n                            triangle_found <= 1'b1;\n                            // No need to check further\n                            state <= NEXT_SUBSET;\n                        end else begin\n                            tri_idx <= tri_idx + 1'b1;\n                        end\n                    end else begin\n                        // No triangle found, update max and ways\n                        if (triangle_found == 1'b0) begin\n                            state <= UPDATE_MAX;\n                        end else begin\n                            state <= NEXT_SUBSET;\n                        end\n                    end\n                end\n\n                UPDATE_MAX: begin\n                    if (popcnt > max_q) begin\n                        max_q <= popcnt;\n                        ways <= 16'd1;\n                    end else if (popcnt == max_q) begin\n                        ways <= ways + 1'b1;\n                    end\n                    state <= NEXT_SUBSET;\n                end\n\n                NEXT_SUBSET: begin\n                    if (subset < 16'hFFFF) begin\n                        subset <= subset + 1'b1;\n                        state <= CHECK_BROKEN;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n\n                DONE: begin\n                    max_queens <= max_q;\n                    num_ways <= ways;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule